'use strict';

// MODULES //

var colorsSet = require( './../colors-set.js' );

/**
* Method to check weather value is valid background color values.
*
* @private
* @name isValidBackgroundColor
* @param {string} value - color value
* @returns {boolean} is valid background color
*/
function isValidBackgroundColor( value ) {
	return colorsSet[value] !== undefined && value.startsWith( 'B' );
}

module.exports = isValidBackgroundColor;
